mapper.select:
select id, activity_id, activity_name, source, channel, goods_id, seckill_price,
       total_count, available_count, lock_count, take_limit_count, status,
       start_time, end_time, create_time, update_time
from seckill_activity
where 1 = 1

    and activity_id = #{activityId}


    and source = #{source}


    and channel = #{channel}


    and goods_id = #{goodsId}

limit 1
